section.sketch:
let billyX = 600;
let jet = 0;

async function setup() {
  createCanvas(800, 600);
  await chargerPersonnages();
}

function draw() {
  background(30);
  dessinerChateau(170, 500, 300);
  dessinerBilly(billyX, 500, 250);
  dessinerRaoul(mouseX, 500, 120);

  if (sontProches(mouseX, 500, billyX, 500, 200)) {
    parler("Qui ose ?", billyX, 230);
  }

  if (jet > 0) {
    parler("Tiens, prends ça : " + jet, mouseX, 340);
  }
}

function mousePressed() {
  jet = lancerDe(20);
}
